import React, { useState } from 'react';
//import { useNavigate } from 'react-router-dom';
import SuccessMessage from '../components/quiz/SuccessMessage';

const QuizPage = () => {
    const [formData, setFormData] = useState({
        exam: "",
        difficultyLevels: [],
        classYear: "",
        name: "",
        quizMode: "",
        addHints: false,
        answerExplanation: false,
        breakIntoSubtopics: false,
        subjects: [],
        topics: [],
        currentSubject: "",
        currentTopic: "",
        numberOfQuestions: "",
        time: "",
        typeOfQuestions: null,
    });

    const [formSubmitted, setFormSubmitted] = useState(false);

    const handleChange = (e) => {
        const { name, value, type, checked } = e.target;
        setFormData((prevData) => ({
            ...prevData,
            [name]: type === "checkbox" ? checked : value,
        }));
    };

    const handleDifficultyChange = (e) => {
        const { value, checked } = e.target;
        setFormData((prevData) => ({
            ...prevData,
            difficultyLevels: checked
                ? [...prevData.difficultyLevels, value]
                : prevData.difficultyLevels.filter((level) => level !== value),
        }));
    };

    const handleSubmit = (event) => {
        event.preventDefault();
        setFormSubmitted(true);
        console.log("Form data submitted : ", formData);
    };

    const handleAddSubject = () => {
        if (formData.currentSubject.trim()) {
            setFormData((prev) => ({
                ...prev,
                subjects: [...prev.subjects, formData.currentSubject.trim()],
                currentSubject: "",
            }));
        }
    };

    const handleAddTopic = () => {
        if (formData.currentTopic.trim()) {
            setFormData((prev) => ({
                ...prev,
                topics: [...prev.topics, formData.currentTopic.trim()],
                currentTopic: "",
            }));
        }
    };

    return (
        <div className="bg-gray-100 min-h-screen flex justify-center items-center">
            <div className="bg-white rounded-lg shadow-lg p-8 w-full max-w-4xl">
                {!formSubmitted ? (
                    <form onSubmit={handleSubmit}>
                        <h1 className="text-2xl font-bold mb-6 text-blue-700">Create Your Quiz</h1>

                        {/* Name Input */}
                        <label className="block text-gray-700 mb-2">What should we call you?</label>
                        <input
                            type="text"
                            name="name"
                            value={formData.name}
                            onChange={handleChange}
                            placeholder="e.g., ABC XYZ"
                            required
                            className="block w-full mb-4 p-2 border rounded-md"
                        />

                        {/* Exam Input */}
                        <label className="block text-gray-700 mb-2">Exam Type</label>
                        <input
                            type="text"
                            name="exam"
                            value={formData.exam}
                            onChange={handleChange}
                            placeholder="e.g., MidTerm, JEE"
                            required
                            className="block w-full mb-4 p-2 border rounded-md"
                        />

                        {/* Difficulty Levels */}
                        <label className="block text-gray-700 mb-2">Select Difficulty Levels</label>
                        <div className="mb-4 flex gap-4">
                            {["Easy", "Medium", "Hard"].map((level) => (
                                <label key={level} className="flex items-center gap-2">
                                    <input
                                        type="checkbox"
                                        value={level}
                                        checked={formData.difficultyLevels.includes(level)}
                                        onChange={handleDifficultyChange}
                                    />
                                    {level}
                                </label>
                            ))}
                        </div>

                        {/* Class Input */}
                        <label className="block text-gray-700 mb-2">Class / College Year</label>
                        <input
                            type="text"
                            name="classYear"
                            value={formData.classYear}
                            onChange={handleChange}
                            placeholder="e.g., Class 11, 3rd Year"
                            required
                            className="block w-full mb-4 p-2 border rounded-md"
                        />

                        {/* Additional Features */}
                        <label className="block text-gray-700 mb-2">Additional Features</label>
                        <div className="mb-4 flex gap-4">
                            {[
                                { label: "Add Hints", name: "addHints" },
                                { label: "Answer Explanation", name: "answerExplanation" },
                                { label: "Break Into Subtopics", name: "breakIntoSubtopics" },
                            ].map((feature) => (
                                <label key={feature.name} className="flex items-center gap-2">
                                    <input
                                        type="checkbox"
                                        name={feature.name}
                                        checked={formData[feature.name]}
                                        onChange={handleChange}
                                    />
                                    {feature.label}
                                </label>
                            ))}
                        </div>

                        {/* Subjects */}
                        <label className="block text-gray-700 mb-2">Add Subjects</label>
                        <div className="flex items-center gap-4 mb-4">
                            <input
                                type="text"
                                name="currentSubject"
                                value={formData.currentSubject}
                                onChange={(e) =>
                                    setFormData((prev) => ({
                                        ...prev,
                                        currentSubject: e.target.value,
                                    }))
                                }
                                placeholder="Add Subject"
                                className="flex-1 p-2 border rounded-md"
                            />
                            <button
                                type="button"
                                onClick={handleAddSubject}
                                className="bg-blue-500 text-white px-4 py-2 rounded-md hover:bg-blue-600"
                            >
                                Add
                            </button>
                        </div>
                        <div className="mb-4">
                            {formData.subjects.map((subject, idx) => (
                                <span key={idx} className="bg-blue-100 text-blue-700 py-1 px-3 rounded-md mr-2">
                                    {subject}
                                </span>
                            ))}
                        </div>

                        {/* Timer Options */}
                        <label className="block text-gray-700 mb-2">Timer Options</label>
                        <div className="mb-4">
                            <label className="flex items-center gap-2">
                                <input type="radio" name="timer" value="noTimer" onChange={() => {}} /> No Timer
                            </label>
                        </div>

                        <div className="text-center">
                            <button
                                type="submit"
                                className="bg-green-500 text-white py-2 px-6 rounded-lg hover:bg-green-600"
                            >
                                Create Quiz
                            </button>
                        </div>
                    </form>
                ) : (
                    <SuccessMessage formData={formData} />
                )}
            </div>
        </div>
    );
};

export default QuizPage;
